/*
 * A319198  Partial sums of the infinite self-similar tribonacci word, written
 *          in the form A080843.
 * https://oeis.org/A319198
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   * a(n) = a(n-1) + A080843(n) (for n ≥ 1) * a(0) = 0 * A080843(n)
 *            is the n‑th digit of the infinite self‑similar Tribonacci * word
 *            generated by 0 → 01, 1 → 02, 2 → 0. The digits are 0,1,2 * and
 *            a(n) is the partial sum of the first n+1 digits (0‑indexed)
 * Range:     u8 n <= 414, u16 n <= 9563, u32 n <= 9563, u64 n <= 9563,
 *            u128 n <= 9563, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>   /* malloc, free */

seq_t a(idx_t n)
{
    /* Current word (digits 0,1,2) and its prefix sums. */
    static unsigned char *w = NULL;   /* word characters */
    static seq_t *pref = NULL;        /* pref[i] = sum of w[0..i] */
    static idx_t w_len = 0;           /* current word length      */

    /* Initialise with the first word "0". */
    if (!w) {
        w_len = 1;
        w = (unsigned char *)malloc(sizeof(unsigned char));
        pref = (seq_t *)malloc(sizeof(seq_t));
        w[0] = 0;
        pref[0] = (seq_t)0;
    }

    /* Expand until we have an index n in pref. */
    while (w_len <= n) {
        /* Determine the length of the next word. */
        idx_t new_len = 0;
        for (idx_t i = 0; i < w_len; ++i) {
            new_len += (w[i] == 2) ? 1 : 2;   /* 0/1 → 2 chars, 2 → 1 char */
        }

        unsigned char *nw = (unsigned char *)malloc(new_len * sizeof(unsigned char));
        seq_t       *np = (seq_t *)malloc(new_len * sizeof(seq_t));

        idx_t pos = 0;
        seq_t running = 0;  /* running sum for the new word */

        for (idx_t i = 0; i < w_len; ++i) {
            unsigned char c = w[i];

            if (c == 0) {
                nw[pos] = 0;
                running += 0;
                np[pos] = running; ++pos;

                nw[pos] = 1;
                running += 1;
                np[pos] = running; ++pos;
            } else if (c == 1) {
                nw[pos] = 0;
                running += 0;
                np[pos] = running; ++pos;

                nw[pos] = 2;
                running += 2;
                np[pos] = running; ++pos;
            } else {   /* c == 2 */
                nw[pos] = 0;
                running += 0;
                np[pos] = running; ++pos;
            }
        }

        /* Replace old word and prefix arrays. */
        free(w);
        free(pref);
        w = nw;
        pref = np;
        w_len = new_len;
    }

    return pref[n];
}
